UPDATE suite.roles SET permissions=ARRAY(SELECT DISTINCT unnest(permissions || ARRAY['billing.manage','contacts.contacts.read','contacts.contacts.write','contacts.notes.read','contacts.notes.write','projects.projects.read','projects.projects.write','projects.tasks.read','projects.tasks.write','projects.comments.read','projects.comments.write','projects.time.read','projects.time.write'])) WHERE protected AND name IN ('Owner','Administrator');
